#include <iostream>
#include <cmath>
#include <iomanip>

// Babylonian square root approximation (Exercise 6.27)
double babylonianSqrt(int n) {
    if (n <= 0) return 0.0;
    double lastGuess = 1.0;
    double nextGuess = (lastGuess + (n / lastGuess)) / 2.0;
    while (std::abs(nextGuess - lastGuess) >= 0.0001) {
        lastGuess = nextGuess;
        nextGuess = (lastGuess + (n / lastGuess)) / 2.0;
    }
    return nextGuess;
}

// Check if sum of digits is prime (Exercise 6.25)
bool isPrime(int n) {
    if (n < 2) return false;
    for (int i = 2; i * i <= n; ++i) {
        if (n % i == 0) return false;
    }
    return true;
}

int sumOfDigits(int n) {
    int sum = 0;
    n = std::abs(n);
    while (n > 0) {
        sum += n % 10;
        n /= 10;
    }
    return sum;
}

int main() {
    int val = 25;
    std::cout << std::fixed << std::setprecision(4);
    std::cout << "Babylonian sqrt(" << val << ") = " << babylonianSqrt(val) << "\n";

    int samplePrime = 29;
    int s = sumOfDigits(samplePrime);
    std::cout << "Number: " << samplePrime << ", Sum: " << s 
              << ", Additive Prime: " << (isPrime(samplePrime) && isPrime(s) ? "true" : "false") << "\n";
    return 0;
}

#include <iostream>

// Deterministic mock dice roller for repeatable testing
int rollDiceMock(int callIndex) {
    // Simulating sequence: 4 + 4 = 8 (point 8), then 6 + 2 = 8 (win)
    const int sequence[] = {4, 4, 6, 2};
    return sequence[callIndex % 4];
}

// Single round of Craps
bool playCrapsDeterministic() {
    int d1 = rollDiceMock(0);
    int d2 = rollDiceMock(1);
    int sum = d1 + d2;
    std::cout << "You rolled " << d1 << " + " << d2 << " = " << sum << "\n";

    if (sum == 7 || sum == 11) {
        std::cout << "You win\n";
        return true;
    }
    if (sum == 2 || sum == 3 || sum == 12) {
        std::cout << "You lose\n";
        return false;
    }

    int point = sum;
    std::cout << "point is " << point << "\n";

    int d3 = rollDiceMock(2);
    int d4 = rollDiceMock(3);
    sum = d3 + d4;
    std::cout << "You rolled " << d3 << " + " << d4 << " = " << sum << "\n";

    if (sum == point) {
        std::cout << "You win\n";
        return true;
    } else {
        std::cout << "You lose\n";
        return false;
    }
}

int main() {
    playCrapsDeterministic();
    return 0;
}

#include <iostream>
#include <string>

// Exercise 6.31: Multiply three numbers in-place via references
void multiply(double& num1, double& num2, double& num3, int constant) {
    num1 *= constant;
    num2 *= constant;
    num3 *= constant;
}

// Exercise 6.30: Reference search
bool searchChar(const std::string& s, char key) {
    for (char c : s) {
        if (c == key) return true;
    }
    return false;
}

int main() {
    double a = 2.5, b = 4.0, c = 10.0;
    int factor = 3;

    std::cout << "Before: " << a << " " << b << " " << c << "\n";
    multiply(a, b, c, factor);
    std::cout << "After multiplying by " << factor << ": " 
              << a << " " << b << " " << c << "\n";

    std::string text = "bilingual";
    char target = 'g';
    std::cout << "Search '" << target << "' in \"" << text << "\": " 
              << (searchChar(text, target) ? "Found" : "Not found") << "\n";
    return 0;
}
